CREATE TABLE app_user(internal_pk BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id VARCHAR(36) UNIQUE NOT NULL, username VARCHAR(80) UNIQUE NOT NULL, display_name VARCHAR(150) NOT NULL, role VARCHAR(20) NOT NULL, password_hash VARCHAR(100) NOT NULL, health_id VARCHAR(64) UNIQUE, organization VARCHAR(100) NOT NULL);
CREATE TABLE consent(internal_pk BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id VARCHAR(36) UNIQUE NOT NULL, patient_id VARCHAR(36) NOT NULL REFERENCES app_user(id), grantee_id VARCHAR(36) NOT NULL REFERENCES app_user(id), purpose VARCHAR(40) NOT NULL, scopes VARCHAR(500) NOT NULL, expires_at VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE INDEX consent_access ON consent(patient_id,grantee_id,status);
CREATE TABLE clinical_record(internal_pk BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id VARCHAR(36) UNIQUE NOT NULL, patient_id VARCHAR(36) NOT NULL REFERENCES app_user(id), kind VARCHAR(40) NOT NULL, title VARCHAR(200) NOT NULL, details TEXT NOT NULL, author_id VARCHAR(36) NOT NULL REFERENCES app_user(id), source VARCHAR(100) NOT NULL, status VARCHAR(30) NOT NULL, created_at VARCHAR(40) NOT NULL, replaces_id VARCHAR(36), related_id VARCHAR(36));
CREATE INDEX record_patient ON clinical_record(patient_id,created_at);
CREATE TABLE access_request(internal_pk BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id VARCHAR(36) UNIQUE NOT NULL, patient_id VARCHAR(36) NOT NULL REFERENCES app_user(id), requester_id VARCHAR(36) NOT NULL REFERENCES app_user(id), purpose VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE audit_event(seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id VARCHAR(36) UNIQUE NOT NULL, actor_id VARCHAR(36), patient_id VARCHAR(36), action VARCHAR(80) NOT NULL, resource_id VARCHAR(100) NOT NULL, occurred_at VARCHAR(40) NOT NULL, previous_hash VARCHAR(64) NOT NULL, event_hash VARCHAR(64) NOT NULL);
